import{_ as s,o as t,c as e,a}from"./app.83c7065c.js";const F=JSON.parse('{"title":"JS中的隐式转换","description":"","frontmatter":{"title":"JS中的隐式转换","date":"2018-09-21"},"headers":[],"relativePath":"2018/js-implicit-coercion.md","lastUpdated":1786184870000}'),l={name:"2018/js-implicit-coercion.md"},n=a(`<ul><li><a href="#date-2018-09-21">date: 2018-09-21</a><ul><li><a href="#%E5%9F%BA%E6%9C%AC%E7%B1%BB%E5%9E%8B%E9%9A%90%E5%BC%8F%E8%BD%AC%E6%8D%A2">基本类型隐式转换</a><ul><li><a href="#%E5%9F%BA%E6%9C%AC%E7%B1%BB%E5%9E%8B%E8%BD%AC%E6%8D%A2%E4%B8%BAboolean%E7%B1%BB%E5%9E%8B">基本类型转换为Boolean类型</a></li><li><a href="#%E5%9F%BA%E6%9C%AC%E7%B1%BB%E5%9E%8B%E8%BD%AC%E6%8D%A2%E4%B8%BAstring%E7%B1%BB%E5%9E%8B">基本类型转换为String类型</a></li><li><a href="#%E5%9F%BA%E6%9C%AC%E7%B1%BB%E5%9E%8B%E8%BD%AC%E6%8D%A2%E4%B8%BAnumber%E7%B1%BB%E5%9E%8B">基本类型转换为Number类型</a></li></ul></li><li><a href="#%E5%AF%B9%E8%B1%A1%E9%9A%90%E5%BC%8F%E8%BD%AC%E6%8D%A2%E4%B8%BA%E5%9F%BA%E6%9C%AC%E7%B1%BB%E5%9E%8B">对象隐式转换为基本类型</a></li></ul></li></ul><hr><h4 id="基本类型隐式转换" tabindex="-1">基本类型隐式转换 <a class="header-anchor" href="#基本类型隐式转换" aria-hidden="true">#</a></h4><h5 id="基本类型转换为boolean类型" tabindex="-1">基本类型转换为Boolean类型 <a class="header-anchor" href="#基本类型转换为boolean类型" aria-hidden="true">#</a></h5><p>隐式转换相当于调用<code>Boolean(value)</code>方法，其底层实现为<code>ToBoolean(value)</code>方法，转换规则如下表:</p><table><thead><tr><th>数据类型</th><th style="text-align:left;">转换为true的值</th><th style="text-align:left;">转换为false的值</th></tr></thead><tbody><tr><td>Boolean</td><td style="text-align:left;">true</td><td style="text-align:left;">false</td></tr><tr><td>String</td><td style="text-align:left;">非空字符串<br>(<code>value.length&gt;0</code>)</td><td style="text-align:left;">空字符串&#39;&#39;<br>(<code>value.length===0</code>)</td></tr><tr><td>Number</td><td style="text-align:left;">非零值</td><td style="text-align:left;">0 或 NaN</td></tr><tr><td>Undefined</td><td style="text-align:left;">\\</td><td style="text-align:left;">false</td></tr><tr><td>Null</td><td style="text-align:left;">\\</td><td style="text-align:left;">false</td></tr><tr><td>Symbol</td><td style="text-align:left;">任何值</td><td style="text-align:left;">\\</td></tr></tbody></table><blockquote><p>注：转换为Boolean为false的值有：<code>&#39;&#39;, false, 0, NaN, undefined, null</code></p></blockquote><p><strong>例1</strong></p><div class="language-javascript"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#82AAFF;">Boolean</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&#39;&#39;</span><span style="color:#A6ACCD;">) </span><span style="color:#676E95;font-style:italic;">//空字符串，0</span></span>
<span class="line"><span style="color:#82AAFF;">Boolean</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;">) </span><span style="color:#676E95;font-style:italic;">//含有一个空格的字符串，1</span></span>
<span class="line"></span></code></pre></div><p><br><br></p><h5 id="基本类型转换为string类型" tabindex="-1">基本类型转换为String类型 <a class="header-anchor" href="#基本类型转换为string类型" aria-hidden="true">#</a></h5><p>隐式转换相当于调用<code>String(value)</code>方法，其底层实现为<code>ToString(value)</code>方法，规则如下表：</p><table><thead><tr><th>数据类型</th><th style="text-align:left;">转换为string的值</th></tr></thead><tbody><tr><td>Boolean</td><td style="text-align:left;">true=&gt;<code>&#39;true&#39;</code><br>false=&gt;<code>&#39;false&#39;</code></td></tr><tr><td>Null</td><td style="text-align:left;"><code>&#39;null&#39;</code></td></tr><tr><td>Undefined</td><td style="text-align:left;"><code>&#39;undefined&#39;</code></td></tr><tr><td>Number</td><td style="text-align:left;">数字的string值</td></tr><tr><td>String</td><td style="text-align:left;">不转换</td></tr><tr><td>Symbol</td><td style="text-align:left;">抛出<code>TypeError</code>异常</td></tr><tr><td><strong>例2</strong></td><td style="text-align:left;"></td></tr></tbody></table><div class="language-javascript"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#82AAFF;">String</span><span style="color:#A6ACCD;">(</span><span style="color:#FF9CAC;">false</span><span style="color:#A6ACCD;">) </span><span style="color:#676E95;font-style:italic;">//&#39;false&#39;</span></span>
<span class="line"><span style="color:#82AAFF;">String</span><span style="color:#A6ACCD;">(</span><span style="color:#F78C6C;">1.32e3</span><span style="color:#A6ACCD;">) </span><span style="color:#676E95;font-style:italic;">//&#39;1320&#39;</span></span>
<span class="line"><span style="color:#82AAFF;">String</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">-Infinity</span><span style="color:#A6ACCD;">) </span><span style="color:#676E95;font-style:italic;">//&#39;-Infinity&#39;</span></span>
<span class="line"><span style="color:#82AAFF;">String</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">NaN</span><span style="color:#A6ACCD;">) </span><span style="color:#676E95;font-style:italic;">// &#39;NaN&#39;</span></span>
<span class="line"></span></code></pre></div><p><br><br></p><h5 id="基本类型转换为number类型" tabindex="-1">基本类型转换为Number类型 <a class="header-anchor" href="#基本类型转换为number类型" aria-hidden="true">#</a></h5><p>隐式转换相当于调用<code>Number(value)</code>方法，底层实现为<code>ToNumber(value)</code>方法，规则如下表：</p><table><thead><tr><th>数据类型</th><th style="text-align:left;">转换为number的值</th></tr></thead><tbody><tr><td>Undefined</td><td style="text-align:left;">NaN</td></tr><tr><td>Null</td><td style="text-align:left;">0</td></tr><tr><td>Boolean</td><td style="text-align:left;">true=&gt; 1<br>false=&gt;0</td></tr><tr><td>Number</td><td style="text-align:left;">不转换</td></tr><tr><td>String</td><td style="text-align:left;">1.空字符串或仅有空格的字符串=&gt;0<br>2.整数=&gt;保留符号，忽略整数中的先导0，返回整数<br>3.浮点数=&gt;保留符号，忽略先导0，返回浮点数<br>4.十六进制数=&gt;返回相同大小的十进制数<br>5.二进制数=&gt;返回相同大小的十进制数<br>6.八进制数=&gt;返回相同大小的十进制数<br>7.科学记数法=&gt;返回相同大小的十进制数<br>8.其他=&gt;返回NaN<br>注：数字字符串中头尾2端的空白，转换时都将被忽略</td></tr><tr><td>Symbol</td><td style="text-align:left;">抛出<code>TypeError</code>异常</td></tr></tbody></table><p><strong>例3</strong></p><div class="language-javascript"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#82AAFF;">Number</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&#39;&#39;</span><span style="color:#A6ACCD;">) </span><span style="color:#676E95;font-style:italic;">//0</span></span>
<span class="line"><span style="color:#82AAFF;">Number</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">    </span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;">) </span><span style="color:#676E95;font-style:italic;">//0</span></span>
<span class="line"><span style="color:#82AAFF;">Number</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;"> -1.33e3 </span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;">) </span><span style="color:#676E95;font-style:italic;">//-1330</span></span>
<span class="line"><span style="color:#82AAFF;">Number</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;"> 0x10</span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;">) </span><span style="color:#676E95;font-style:italic;">//16</span></span>
<span class="line"><span style="color:#82AAFF;">Number</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;"> 1232 4345</span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;">) </span><span style="color:#676E95;font-style:italic;">//NaN</span></span>
<span class="line"></span></code></pre></div><p><br><br></p><hr><h4 id="对象隐式转换为基本类型" tabindex="-1">对象隐式转换为基本类型 <a class="header-anchor" href="#对象隐式转换为基本类型" aria-hidden="true">#</a></h4><p>对象转换为基本类型时：</p><ol><li>首先调用<code>ToPrimitive ( input [, PreferredType] )</code>方法，当<code>input</code>可转换为多种基本类型时，可选参数<code>PrefreredType</code>指定优先转换类型</li><li>随后调用<code>OrdinaryToPrimitive(input,hint)</code>方法，其中<code>hint</code>值由<code>PrefreredType</code>决定，且为以下之一：<code>[&quot;default&quot;, &quot;string&quot;, &quot;number&quot;]</code>: <ol><li>如果<code>PrefreredType</code>值为<code>hint String</code>, 则 <code>hint</code>值为<code>&quot;string&quot;</code>，依次调用对象的<code>toString, valueOf</code>方法，直至返回值为基本类型</li><li>如果<code>PrefreredType</code>值为<code>hint Number</code>, 则 <code>hint</code>值为<code>&quot;number&quot;</code>，依次调用对象的<code>valueOf, toString</code>方法，直至返回值为基本类型</li><li>如果<code>PrefreredType</code>未指定, 则 <code>hint</code>值为<code>&quot;default&quot;</code>，按2步骤执行</li><li>如果上述执行完毕后，返回值仍不是基本类型，抛出<code>TypeError</code>异常</li></ol></li></ol><blockquote><p>注：<br> 1.<code>Date</code>对象在转换时，其<code>PrefreredType</code>为<code>hint String</code><br> 2.以上对象默认转换规则，如果对象重写了默认的<code>toString</code> 和/或 <code>valueOf</code>方法，致使无法返回基本类型，那么将抛出<code>TypeError</code>异常</p></blockquote><p><strong>例4</strong></p><div class="language-javascript"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#C792EA;">let</span><span style="color:#A6ACCD;"> a </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">{};</span></span>
<span class="line"><span style="color:#A6ACCD;">a</span><span style="color:#89DDFF;">+</span><span style="color:#F78C6C;">1</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">//&#39;[object Object]1&#39;</span></span>
<span class="line"><span style="color:#A6ACCD;">a</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">toString</span><span style="color:#A6ACCD;">() </span><span style="color:#676E95;font-style:italic;">//&#39;[object Object]&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C792EA;">function</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">Test</span><span style="color:#89DDFF;">(){</span></span>
<span class="line"><span style="color:#F07178;">    </span><span style="color:#89DDFF;">this.</span><span style="color:#82AAFF;">valueOf</span><span style="color:#F07178;"> </span><span style="color:#89DDFF;">=</span><span style="color:#F07178;"> </span><span style="color:#C792EA;">function</span><span style="color:#89DDFF;">(){</span><span style="color:#89DDFF;font-style:italic;">return</span><span style="color:#F07178;"> </span><span style="color:#F78C6C;">112233</span><span style="color:#89DDFF;">}</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"><span style="color:#A6ACCD;">a </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">new</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">Test</span><span style="color:#A6ACCD;">()</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#A6ACCD;">a</span><span style="color:#89DDFF;">+</span><span style="color:#F78C6C;">1</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">//112234</span></span>
<span class="line"><span style="color:#82AAFF;">String</span><span style="color:#A6ACCD;">(a) </span><span style="color:#676E95;font-style:italic;">//&#39;[object Object]&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C792EA;">function</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">Test2</span><span style="color:#89DDFF;">(){</span></span>
<span class="line"><span style="color:#F07178;">  </span><span style="color:#89DDFF;">this.</span><span style="color:#82AAFF;">toString</span><span style="color:#F07178;"> </span><span style="color:#89DDFF;">=</span><span style="color:#F07178;"> </span><span style="color:#C792EA;">function</span><span style="color:#89DDFF;">(){</span><span style="color:#89DDFF;font-style:italic;">return</span><span style="color:#F07178;"> []</span><span style="color:#89DDFF;">};</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"><span style="color:#A6ACCD;">a</span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">new</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">Test2</span><span style="color:#A6ACCD;">()</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#A6ACCD;">a</span><span style="color:#89DDFF;">+</span><span style="color:#F78C6C;">1</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">//TypeError: Cannot convert object to primitive value </span></span>
<span class="line"></span></code></pre></div><ul><li>上例中，先将a声明为空对象，<code>a+1</code>进行计算时，a按照规则2.3进行转换，先根据原型链调用<code>Object.valueOf()</code>方法，返回对象自身，然后继续调用<code>Object.toString()</code>方法返回值<code>&#39;[object Object]&#39;</code>，最后将a和数字1进行字符串拼接，得到结果；</li><li>之后将a声明为<code>Test</code>类的实例对象，<code>Test</code>中重写了<code>valueOf()</code>方法，再次进行<code>a+1</code>计算时，按照规则2.3进行转换，此时<code>valueOf()</code>方法返回值为基本类型，不再继续调用<code>toString()</code>方法，于是结果变为<code>112234</code>；而调用<code>String(a)</code>将对象优先转换为<code>string</code>类型，仍然调用的是<code>Object.toString()</code>方法，结果与之前相同</li><li>再次声明<code>Test2</code>类，确保其2个方法都没有返回基本类型，再次计算实例<code>a+1</code>时，抛出了<code>TypeError</code>错误</li></ul>`,29),o=[n];function p(c,r,d,i,y,A){return t(),e("div",null,o)}const C=s(l,[["render",p]]);export{F as __pageData,C as default};
